def compute(vars):
    network_solutions_revenue = vars["v1"]
    services_support_revenue = vars["v2"]
    difference = network_solutions_revenue - services_support_revenue

    return {
        "value": difference,
        "trace": {
            "network_solutions_revenue": network_solutions_revenue,
            "services_support_revenue": services_support_revenue,
            "difference": difference,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
